import sympy
from sympy import symbols, groebner, reduced, factor_list

# Top-level setup for standard variables
x, y, z = symbols('x y z')

CONDITION_LABELS = [
    "H_1: M is a finitely generated torsion R-module whose annihilator is generated by a",
    "H_2: p is a prime element of R",
    "¬Q: The p-primary component of M is non-zero, but p does not divide a in R"
]

N_HYP = 2
NEG_Q_INDEX = 2

def is_in_ideal(f, I_gens, vars):
    I_gens = [g for g in I_gens if g != 0]
    if not I_gens:
        return sympy.expand(f) == 0
    gb = groebner(I_gens, *vars, domain='QQ')
    return reduced(f, gb, vars, domain='QQ')[1] == 0

def ideal_intersection(I1, I2, vars):
    if not I1 or not I2:
        return []
    t = sympy.Dummy('t')
    gens = [t * g for g in I1] + [(1 - t) * g for g in I2]
    gens = [g for g in gens if g != 0]
    if not gens:
        return []
    gb = list(groebner(gens, t, *vars, order='lex', domain='QQ'))
    return [g for g in gb if t not in g.free_symbols]

def conditions(witness):
    """
    witness is expected to be a dictionary representing a module M = \bigoplus R/I_j over R = QQ[vars].
    Keys:
      'vars': tuple of SymPy symbols (e.g., (x, y))
      'I_list': list of lists of polynomials, where each inner list generates an ideal I_j.
      'a': polynomial generating the annihilator of M.
      'p': polynomial representing the prime element.
      'm_list': list of polynomials representing an element m in M (one component for each I_j).
      'k': integer such that p^k * m = 0 in M.
    """
    try:
        vars = witness['vars']
        I_list = witness['I_list']
        a = witness['a']
        p = witness['p']
        m_list = witness['m_list']
        k = witness['k']
    except (TypeError, KeyError):
        return [False, False, False]

    # H_1: M is a finitely generated torsion R-module whose annihilator is generated by a
    try:
        if not I_list:
            h1 = False
        elif a == 0:
            h1 = False
        else:
            Ann = I_list[0]
            for i in range(1, len(I_list)):
                Ann = ideal_intersection(Ann, I_list[i], vars)
            
            a_in_Ann = is_in_ideal(a, Ann, vars)
            gens_in_a = True
            for g in Ann:
                if reduced(g, [a], vars, domain='QQ')[1] != 0:
                    gens_in_a = False
                    break
            h1 = a_in_Ann and gens_in_a
    except Exception:
        h1 = False

    # H_2: p is a prime element of R
    try:
        if p == 0:
            h2 = False
        elif len(p.free_symbols.intersection(vars)) == 0:
            h2 = False
        else:
            factors = factor_list(p, domain='QQ')
            h2 = (len(factors[1]) == 1 and factors[1][0][1] == 1)
    except Exception:
        h2 = False

    # ¬Q: The p-primary component of M is non-zero, but p does not divide a in R
    try:
        if len(m_list) != len(I_list):
            neg_q = False
        else:
            # Check if m is non-zero in M
            m_is_nonzero = False
            for m_j, I_j in zip(m_list, I_list):
                if not is_in_ideal(m_j, I_j, vars):
                    m_is_nonzero = True
                    break
            
            # Check if m is annihilated by p^k
            m_is_annihilated = True
            for m_j, I_j in zip(m_list, I_list):
                if not is_in_ideal((p**k) * m_j, I_j, vars):
                    m_is_annihilated = False
                    break
            
            P_witness = m_is_nonzero and m_is_annihilated
            
            # Check if p divides a
            Q_eval = (reduced(a, [p], vars, domain='QQ')[1] == 0)
            
            neg_q = P_witness and not Q_eval
    except Exception:
        neg_q = False

    return [h1, h2, neg_q]